%% analyze_servo_prps_amplitude_sweep.m
% Servo amplitude-bandwidth sweep: map achievable vectoring bandwidth
% f_vec(theta_amp) across a ladder of angle amplitudes, then invert the
% feasibility thrust trade to the minimum thrust that stays in spec.
%
% Campaign (firmware servo_prps_log.orchestrate.json, generated by
% tools/design_servo_prps_excitation.py --amplitude-ladder):
%   Each angle-amplitude RUNG (run_name "ladder_aNN_...") carries:
%     - a linear PRPS block ("ladder_aNN_lin_rKK"): several crest-min
%       realizations, top frequency capped at min(0.9*f_slew(theta), coherence
%       ceiling), so the response stays linear -> FOPD (K,tau,L)(theta), corner
%       f_c(theta) = 1/(2*pi*tau).
%     - slew probes ("ladder_aNN_probe_fX") on the large rungs whose slew knee
%       sits inside the trusted band: single tones bracketing and pushing a bit
%       past f_slew(theta). Describing-function gain droop + THD locate the
%       measured slew knee f_slew(theta).
%
% Effective vectoring bandwidth per rung:
%   f_vec(theta) = min( f_c(theta) , f_slew(theta) )
% corner-limited (flat) at small amplitude, slew-limited (~1/theta) at large.
%
% Feasibility inversion (analysis/feasibility/analyze_thrust_angle_bandwidth_trade.m
% writes data/processed/feasibility/thrust_angle_bandwidth_trade.csv):
%   The campaign supplies the measured f_vec(theta) that is compared against
%   the true M3 disturbance-rejection crossover and the purchase-facing 10 Hz
%   vectoring-bandwidth target in docs/feasibility.md and docs/hardware_selection.md.
%
% Empirical transfer function: G(jw) = theta_rad(jw) / command_delta_us(jw) [rad/us]

clearvars -except DATASET_STATUS SAVE_FIGURES;
clc; close all;

%% User options

if ~exist("SAVE_FIGURES", "var"), SAVE_FIGURES = true; end
if ~exist("DATASET_STATUS", "var")
    DATASET_STATUS = "candidate";
else
    DATASET_STATUS = string(DATASET_STATUS);
end
if ~exist("N_BOOT", "var"), N_BOOT = 200; end   % per-rung bootstrap draws (UQ)
if ~exist("RNG_SEED", "var"), RNG_SEED = 1;  end

% Which rung is the reported NOMINAL operating-amplitude model (deg). The store +
% docs quote this rung; its bootstrap CI is the statistical uncertainty and the
% held-out time-domain validation is run on it.
NOMINAL_THETA_DEG = 15;

LADDER_PREFIX = "ladder_";      % run_name prefix that selects this campaign
LIN_TOKEN     = "_lin";
PROBE_TOKEN   = "_probe";

% Measured upgraded-servo context (2026-06-29 step test; used only for the
% slew-knee formula on UN-probed rungs and for annotation).
SLEW_EST_DEG_S = 900.0;
CORNER_EST_HZ  = 9.0;
COH_CEILING_HZ = 15.0;
M3_REQUIRED_CROSSOVER_HZ = sqrt(1.0 / (0.45 * 0.015)) / (2*pi);
PURCHASE_TARGET_BW_HZ = 10.0;

% Knee-detection thresholds on the probe tones.
GAIN_DROOP_DB = 3.0;    % gain this far below the rung's linear low-freq gain
THD_THRESH    = 0.10;   % or angle THD at/above this
N_HARMONICS   = 5;      % harmonics summed for THD

MIN_COHERENCE_FOR_FIT = 0.60;

%% FRF / fit options (mirror analyze_servo_prps_two_band.m; band widened to the
%  coherence ceiling so small-rung linear blocks resolve the ~9 Hz corner).

COUNTS_PER_REV          = encoderAngleScale().counts_per_rev;
DEFAULT_SERVO_CENTER_US = 1428;   % campaign center (firmware truth)
SERVO_OUTPUT_SIGN       = -1;     % command_delta_us up -> theta down
DEFAULT_FREQ_LABEL      = "ladder";

FRF_OPTS = struct();
FRF_OPTS.inferFreqsFromInput       = true;
FRF_OPTS.freqListHz                = [];
FRF_OPTS.inputBinRelativeThreshold = 0.05;
FRF_OPTS.freqMinHz                 = 0.2;
FRF_OPTS.freqMaxHz                 = COH_CEILING_HZ + 0.5;
FRF_OPTS.removePeriodMean          = true;
FRF_OPTS.detrendEachPeriod         = false;
FRF_OPTS.minPeriodsPerRun          = 2;
FRF_OPTS.minSamplesPerPeriod       = 20;
FRF_OPTS.useNominalCommandDtForFrf = true;
FRF_OPTS.nominalCommandDtS         = 0.005;

FIT_OPTS = struct();
FIT_OPTS.weightingMode             = "relative_with_coh";
FIT_OPTS.gainFloorMode             = "fraction_of_median";
FIT_OPTS.gainFloorFractionOfMedian = 0.20;
FIT_OPTS.manualGainFloor           = 1e-5;
FIT_OPTS.initialK                  = pi / 2000;
FIT_OPTS.initialTau                = 0.018;
FIT_OPTS.initialDelay              = 0.030;
FIT_OPTS.initialTau2               = 0.02;
FIT_OPTS.minTau                    = 0.003;
FIT_OPTS.maxTau                    = 2.0;
FIT_OPTS.minDelay                  = 0.0;
FIT_OPTS.maxDelay                  = 0.50;
FIT_OPTS.minGainAbs                = 1e-5;
FIT_OPTS.maxGainAbs                = 0.01;
FIT_OPTS.maxIter                   = 5000;
FIT_OPTS.maxEval                   = 10000;

%% Locate data / output folders

scriptPath = mfilename("fullpath");
repoRoot   = findRepoRoot(scriptPath);
addpath(fullfile(repoRoot, "analysis", "utils"));

dataDir = getMirroredRawDataDir(scriptPath, DATASET_STATUS);
plotDir = getMirroredPlotDir(scriptPath);
relativeAnalysisDir = getRelativeAnalysisDir(scriptPath);
reportDir = fullfile(repoRoot, "reports", relativeAnalysisDir);
processedDir = fullfile(repoRoot, "data", "processed", relativeAnalysisDir);

if ~isfolder(reportDir), mkdir(reportDir); end
if ~isfolder(processedDir), mkdir(processedDir); end

if ~isfolder(dataDir)
    error("Data folder not found:\n%s", dataDir);
end

csvFiles = dir(fullfile(dataDir, "*.csv"));
if isempty(csvFiles)
    error("No CSV files in:\n%s\nRun the amplitude-ladder campaign first.", dataDir);
end
[~, sortIdx] = sort(string({csvFiles.name}));
csvFiles = csvFiles(sortIdx);

fprintf("\nServo PRPS amplitude-bandwidth sweep\n");
fprintf("  Dataset: %s\n", dataDir);
fprintf("  CSV files: %d\n", numel(csvFiles));

%% Load, normalize, keep only ladder PRPS-segment rows

Tall = ServoPrpsId.readCombinedCsvTables(csvFiles);
Tall = ServoPrpsId.normalizeServoPrpsTable( ...
    Tall, COUNTS_PER_REV, DEFAULT_SERVO_CENTER_US, DEFAULT_FREQ_LABEL, SERVO_OUTPUT_SIGN);

Tall = Tall(strcmpi(string(Tall.segment), "prps"), :);
isLadder = startsWith(string(Tall.run_name), LADDER_PREFIX);
Tall = Tall(isLadder, :);
if isempty(Tall)
    error("No ""%s*"" PRPS rows found. Is this the amplitude-ladder campaign?", LADDER_PREFIX);
end

runNames = unique(string(Tall.run_name), "stable");
rungTags = ladderTagOf(runNames);                 % "a08" etc
uniqueTags = unique(rungTags, "stable");
thetaDeg  = arrayfun(@(t) str2double(extractAfter(t, "a")), uniqueTags);
[thetaDeg, order] = sort(thetaDeg);
uniqueTags = uniqueTags(order);
nRung = numel(uniqueTags);

fprintf("  Rungs: %d  (%s deg)\n", nRung, strjoin(string(thetaDeg(:).'), ", "));

%% Per-rung analysis

rungTemplate = struct("theta_deg", NaN, "tag", "", "amp_us", NaN, ...
    "K", NaN, "tau_s", NaN, "delay_s", NaN, "fc_hz", NaN, "linGainDc", NaN, ...
    "nLinLines", NaN, "cohEdgeHz", NaN, ...
    "K_ci", [NaN NaN], "tau_ci", [NaN NaN], "delay_ci", [NaN NaN], "nBootOk", 0, ...
    "probe_f", [], "probe_gain", [], "probe_droopDb", [], "probe_thd", [], ...
    "knee_hz", NaN, "knee_source", "", "f_vec_hz", NaN);
rung = repmat(rungTemplate, nRung, 1);
nominalBootCloud = [];   % [nOk x 3] = [K tau delay] for the nominal rung (UQ + plots)
nominalDlin = table();   % the nominal rung's cleaned linear data (time-domain validation)
nominalFrf = [];         % the nominal rung's pooled FRF (Bode + structure comparison)
nominalFitMask = [];

for i = 1:nRung
    tag = uniqueTags(i);
    theta = thetaDeg(i);

    isThis = rungTags == tag;
    thisRuns = runNames(isThis);
    linRuns   = thisRuns(contains(thisRuns, LIN_TOKEN));
    probeRuns = thisRuns(contains(thisRuns, PROBE_TOKEN));

    r = struct();
    r.theta_deg = theta;
    r.tag = tag;

    % ---- linear block -> FOPD ----
    Dlin = ServoPrpsId.cleanServoPrpsTable( ...
        Tall(ismember(string(Tall.run_name), linRuns), :));
    r.amp_us = max(abs(ServoPrpsId.forceNumeric(Dlin.command_delta_us)), [], "omitnan");

    frf = ServoPrpsId.estimatePrpsFrfFromTable(Dlin, "lin_" + tag, "lin", FRF_OPTS);
    fitMask = frf.coherence >= MIN_COHERENCE_FOR_FIT & isfinite(frf.G_emp);
    if nnz(fitMask) < 2
        warning("Rung %s: <2 coherent linear FRF points; skipping FOPD.", tag);
        r.K = NaN; r.tau_s = NaN; r.delay_s = NaN; r.fc_hz = NaN; r.linGainDc = NaN;
        r.nLinLines = nnz(fitMask); r.cohEdgeHz = NaN;
    else
        m = ServoPrpsId.fitOneFrequencyModel("first_order_delay", ...
            frf.f_Hz(fitMask), frf.G_emp(fitMask), frf.coherence(fitMask), FIT_OPTS);
        r.K = m.K; r.tau_s = m.tau1_s; r.delay_s = m.delay_s;
        r.fc_hz = 1 / (2*pi*m.tau1_s);
        r.linGainDc = abs(m.K);           % low-frequency gain reference (rad/us)
        r.nLinLines = nnz(fitMask);
        r.cohEdgeHz = contiguousCoherenceEdge(frf, MIN_COHERENCE_FOR_FIT);

        % --- bootstrap UQ: statistical 95% CI on (K,tau,L) for this rung ---
        % Resample whole PRPS periods with replacement (stratified by realization
        % run_name), refit the same FOPD, accumulate the (K,tau,L) cloud. This is
        % the per-rung STATISTICAL uncertainty; the across-rung spread (the
        % amplitude-dependence) is the separate, dominant systematic window.
        [r.K_ci, r.tau_ci, r.delay_ci, r.nBootOk, bootCloud] = bootstrapRungFopd( ...
            Dlin, FRF_OPTS, FIT_OPTS, MIN_COHERENCE_FOR_FIT, N_BOOT, RNG_SEED + i);
        fprintf("       boot(%d ok): K[%.4g,%.4g] tau[%.1f,%.1f]ms L[%.1f,%.1f]ms\n", ...
            r.nBootOk, r.K_ci(1), r.K_ci(2), r.tau_ci(1)*1e3, r.tau_ci(2)*1e3, ...
            r.delay_ci(1)*1e3, r.delay_ci(2)*1e3);
        if abs(theta - NOMINAL_THETA_DEG) < 1e-9
            nominalBootCloud = bootCloud;   % [nOk x 3] = [K tau delay]
            nominalDlin = Dlin;
            nominalFrf = frf;
            nominalFitMask = fitMask;
        end
    end

    % ---- slew probes -> describing-function gain droop + THD ----
    nProbeRuns = numel(probeRuns);
    pf = nan(nProbeRuns, 1); pg = nan(nProbeRuns, 1);
    pd = nan(nProbeRuns, 1); pt = nan(nProbeRuns, 1);
    nProbeMeas = 0;
    for j = 1:numel(probeRuns)
        Dp = ServoPrpsId.cleanServoPrpsTable( ...
            Tall(string(Tall.run_name) == probeRuns(j), :));
        meas = measureProbeTone(Dp, FRF_OPTS.nominalCommandDtS, N_HARMONICS);
        if isempty(meas) || ~isfinite(meas.gain_abs)
            continue;
        end
        nProbeMeas = nProbeMeas + 1;
        pf(nProbeMeas) = meas.f_hz;
        pg(nProbeMeas) = meas.gain_abs;
        pt(nProbeMeas) = meas.thd;
        refGain = r.linGainDc;
        if ~isfinite(refGain) || refGain <= 0, refGain = meas.gain_abs; end
        pd(nProbeMeas) = 20*log10(meas.gain_abs / refGain);
    end
    pf = pf(1:nProbeMeas); pg = pg(1:nProbeMeas);
    pd = pd(1:nProbeMeas); pt = pt(1:nProbeMeas);
    [pf, si] = sort(pf); pg = pg(si); pd = pd(si); pt = pt(si);
    r.probe_f = pf; r.probe_gain = pg; r.probe_droopDb = pd; r.probe_thd = pt;

    % ---- knee ----
    if isempty(pf)
        r.knee_hz = SLEW_EST_DEG_S / (2*pi*theta);   % formula (knee above band)
        r.knee_source = "slew-formula (unprobed)";
    else
        [kneeHz, src] = findKnee(pf, pd, pt, GAIN_DROOP_DB, THD_THRESH);
        r.knee_hz = kneeHz; r.knee_source = src;
    end

    % ---- effective vectoring bandwidth ----
    r.f_vec_hz = min([r.fc_hz, r.knee_hz], [], "omitnan");

    rung(i) = r;

    fprintf("  %-4s theta=%2.0f deg | K=%.4g tau=%.1f ms fc=%.2f Hz | knee=%.2f Hz (%s) | f_vec=%.2f Hz\n", ...
        tag, theta, r.K, r.tau_s*1e3, r.fc_hz, r.knee_hz, r.knee_source, r.f_vec_hz);
end

thetaArr = [rung.theta_deg].';
fcArr    = [rung.fc_hz].';
kneeArr  = [rung.knee_hz].';
fvecArr  = [rung.f_vec_hz].';

% Per-rung bootstrap CI bounds as columns (rung is nRung-by-1, so arrayfun
% already returns column vectors -- no transpose).
Kcilo   = arrayfun(@(r) r.K_ci(1),     rung);   Kcihi   = arrayfun(@(r) r.K_ci(2),     rung);
taucilo = arrayfun(@(r) r.tau_ci(1),   rung);   taucihi = arrayfun(@(r) r.tau_ci(2),   rung);
Lcilo   = arrayfun(@(r) r.delay_ci(1), rung);   Lcihi   = arrayfun(@(r) r.delay_ci(2), rung);

summaryTable = table( ...
    thetaArr, ...
    [rung.amp_us].', ...
    [rung.K].', Kcilo, Kcihi, ...
    [rung.tau_s].', taucilo, taucihi, ...
    [rung.delay_s].', Lcilo, Lcihi, ...
    fcArr, ...
    [rung.nLinLines].', ...
    [rung.cohEdgeHz].', ...
    arrayfun(@(r) r.nBootOk, rung), ...
    kneeArr, ...
    string({rung.knee_source}).', ...
    fvecArr, ...
    'VariableNames', { ...
        'theta_amp_deg', ...
        'amplitude_us', ...
        'K_rad_per_us', 'K_ci_lo', 'K_ci_hi', ...
        'tau_s', 'tau_ci_lo_s', 'tau_ci_hi_s', ...
        'delay_s', 'delay_ci_lo_s', 'delay_ci_hi_s', ...
        'linear_corner_Hz', ...
        'num_coherent_linear_lines', ...
        'coherence_edge_Hz', ...
        'n_bootstrap_ok', ...
        'slew_knee_Hz', ...
        'knee_source', ...
        'f_vec_Hz'});
summaryTable.M3_crossover_pass = summaryTable.f_vec_Hz >= M3_REQUIRED_CROSSOVER_HZ;
summaryTable.purchase_target_pass = summaryTable.f_vec_Hz >= PURCHASE_TARGET_BW_HZ;

% --- Amplitude-dependence window (systematic) vs statistical scatter ---
% The reported nominal is the NOMINAL_THETA_DEG rung; the design uncertainty window
% is the min/max of each parameter across the rungs (the amplitude-dependence). We
% also record the widest per-rung bootstrap half-width so the docs can state that
% the systematic window dominates the statistical scatter.
window = struct();
window.K_lo   = min([rung.K].');   window.K_hi   = max([rung.K].');
window.tau_lo = min([rung.tau_s].'); window.tau_hi = max([rung.tau_s].');
window.L_lo   = min([rung.delay_s].'); window.L_hi = max([rung.delay_s].');
inom = find(abs(thetaArr - NOMINAL_THETA_DEG) < 1e-9, 1);
if isempty(inom), inom = numel(rung); end
window.nominal_theta_deg = rung(inom).theta_deg;
window.nominal_K = rung(inom).K; window.nominal_tau = rung(inom).tau_s; window.nominal_L = rung(inom).delay_s;
window.nominal_K_ci = rung(inom).K_ci; window.nominal_tau_ci = rung(inom).tau_ci; window.nominal_L_ci = rung(inom).delay_ci;

fprintf("\nNominal rung (%.0f deg): K=%.6g [%.6g,%.6g], tau=%.1f [%.1f,%.1f] ms, L=%.1f [%.1f,%.1f] ms\n", ...
    window.nominal_theta_deg, window.nominal_K, window.nominal_K_ci(1), window.nominal_K_ci(2), ...
    window.nominal_tau*1e3, window.nominal_tau_ci(1)*1e3, window.nominal_tau_ci(2)*1e3, ...
    window.nominal_L*1e3, window.nominal_L_ci(1)*1e3, window.nominal_L_ci(2)*1e3);
fprintf("Amplitude window: K[%.6g,%.6g] tau[%.1f,%.1f]ms L[%.1f,%.1f]ms\n", ...
    window.K_lo, window.K_hi, window.tau_lo*1e3, window.tau_hi*1e3, window.L_lo*1e3, window.L_hi*1e3);

% --- Held-out time-domain validation of the CHOSEN nominal model ---
% lsim the chosen (nominal-rung pooled) FOPD on one measured realization of that
% rung and score VAF / NRMSE-fit. This translates the frequency-domain fit into the
% time domain against measured angle -- the control-relevant confirmation.
nominalModel = struct("model_type", "first_order_delay", ...
    "K", window.nominal_K, "tau1_s", window.nominal_tau, "delay_s", window.nominal_L);

% Held-out realization for time-domain scoring: ONE source file (a single
% continuous realization) so the uniform grid never bridges an inter-file gap.
Dval = table(); valLabel = "";
if ~isempty(nominalDlin) && height(nominalDlin) > 5
    valFiles = unique(ServoPrpsId.forceNumeric(nominalDlin.source_file_index), "stable");
    Dval = nominalDlin(ServoPrpsId.forceNumeric(nominalDlin.source_file_index) == valFiles(end), :);
    valLabel = string(nominalDlin.run_name(find(ServoPrpsId.forceNumeric(nominalDlin.source_file_index) == valFiles(end), 1)));
end

tdv = struct("ok", false);
if ~isempty(Dval) && height(Dval) > 5
    tdv = computeTimeDomainValidation(Dval, nominalModel, valLabel);
    if tdv.ok
        fprintf("Time-domain validation (%s): VAF=%.1f%%, NRMSE-fit=%.1f%%\n", ...
            tdv.run_name, tdv.vaf, tdv.nrmse_fit);
    end
end

% --- Model-structure comparison on the nominal rung (structural / model-order UQ) ---
% Fit all four candidate structures to the nominal-rung FRF and compare train FRF
% error + held-out time-domain VAF. If a richer structure is materially better, it
% is a model-mismatch candidate for the uncertainty sweep; if the simple FOPD is
% within tolerance, structural uncertainty is negligible and FOPD is sufficient.
STRUCTS        = ["first_order","first_order_delay","second_order_lag","second_order_lag_delay"];
STRUCT_NPARAMS = [2 3 3 4];
SIMPLICITY_TOL = 0.05;   % simplest structure within 5% of best train error wins
structCmp = struct([]);
if ~isempty(nominalFrf) && ~isempty(nominalFrf.f_Hz) && any(nominalFitMask)
    for k = 1:numel(STRUCTS)
        mk = ServoPrpsId.fitOneFrequencyModel(STRUCTS(k), ...
            nominalFrf.f_Hz(nominalFitMask), nominalFrf.G_emp(nominalFitMask), ...
            nominalFrf.coherence(nominalFitMask), FIT_OPTS);
        s = struct("model_type", STRUCTS(k), "n_params", STRUCT_NPARAMS(k), ...
            "train_err", mk.train_weighted_error, "train_mag_dB", mk.train_mag_rmse_dB, ...
            "train_ph_deg", mk.train_phase_rmse_deg, "vaf", NaN, "model", mk);
        if ~isempty(Dval) && height(Dval) > 5
            td = computeTimeDomainValidation(Dval, mk, "struct");
            if td.ok, s.vaf = td.vaf; end
        end
        if isempty(structCmp), structCmp = s; else, structCmp(end+1) = s; end %#ok<AGROW>
    end
    errs = [structCmp.train_err]; vafs = [structCmp.vaf];
    [~, bestK] = min(errs); structBest = structCmp(bestK).model_type;
    iFopd = find([structCmp.model_type] == "first_order_delay", 1);
    [bestVaf, iBV] = max(vafs); fopdVaf = structCmp(iFopd).vaf;
    structuralNegligible = (bestVaf - fopdVaf) <= 0.5;   % held-out VAF margin

    fprintf("\nModel-structure comparison (nominal %.0f deg rung):\n", NOMINAL_THETA_DEG);
    for k = 1:numel(structCmp)
        fprintf("  %-24s np=%d train_err=%.4f mag=%.3f dB VAF=%.1f%%\n", ...
            structCmp(k).model_type, structCmp(k).n_params, structCmp(k).train_err, ...
            structCmp(k).train_mag_dB, structCmp(k).vaf);
    end
    fprintf("  best train_err: %s | best held-out VAF: %s (%.1f%% vs FOPD %.1f%%) | structural UQ negligible: %s\n", ...
        structBest, structCmp(iBV).model_type, bestVaf, fopdVaf, ternaryStr(structuralNegligible, "yes", "no"));
end

probeTable = table();
for i = 1:numel(rung)
    if isempty(rung(i).probe_f), continue; end
    Ti = table( ...
        repmat(rung(i).theta_deg, numel(rung(i).probe_f), 1), ...
        rung(i).probe_f(:), ...
        rung(i).probe_gain(:), ...
        rung(i).probe_droopDb(:), ...
        rung(i).probe_thd(:), ...
        'VariableNames', {'theta_amp_deg', 'probe_frequency_Hz', ...
            'gain_abs_rad_per_us', 'gain_droop_dB', 'angle_THD'});
    probeTable = [probeTable; Ti]; %#ok<AGROW>
end

%% Requirement checks

req = struct();
req.m3CrossoverHz = M3_REQUIRED_CROSSOVER_HZ;
req.purchaseTargetHz = PURCHASE_TARGET_BW_HZ;
req.minMeasuredFvecHz = min(fvecArr, [], "omitnan");
req.maxMeasuredFvecHz = max(fvecArr, [], "omitnan");
finiteFvec = isfinite(fvecArr);
req.allM3Pass = any(finiteFvec) && all(fvecArr(finiteFvec) >= M3_REQUIRED_CROSSOVER_HZ);
req.allPurchasePass = any(finiteFvec) && all(fvecArr(finiteFvec) >= PURCHASE_TARGET_BW_HZ);

fprintf("\nRequirement checks:\n");
fprintf("  M3 crossover requirement        : %.2f Hz -> %s\n", ...
    req.m3CrossoverHz, ternaryStr(req.allM3Pass, "PASS", "FAIL"));
fprintf("  Purchase-facing bandwidth target: %.2f Hz -> %s\n", ...
    req.purchaseTargetHz, ternaryStr(req.allPurchasePass, "PASS", "FAIL"));
fprintf("  Measured f_vec range            : %.2f .. %.2f Hz\n", ...
    req.minMeasuredFvecHz, req.maxMeasuredFvecHz);

%% Plots

cCorner = [0 0.7 1]; cKnee = [1 0.55 0]; cVec = [0.45 1 0.45];
cReq = [0.95 0.2 0.5]; cPts = [1 1 1];

% (1) f_vec vs angle amplitude
figVec = figure("Name", "amp_sweep_fvec", "Color", "w"); hold on; grid on;
plot(thetaArr, fcArr,   "-o", "Color", cCorner, "LineWidth", 1.8, "MarkerFaceColor", cCorner, "DisplayName", "linear corner f_c");
plot(thetaArr, kneeArr, "-s", "Color", cKnee,   "LineWidth", 1.8, "MarkerFaceColor", cKnee,   "DisplayName", "slew knee f_{slew}");
plot(thetaArr, fvecArr, "-^", "Color", cVec,    "LineWidth", 2.4, "MarkerFaceColor", cVec,    "DisplayName", "f_{vec} = min");
yline(COH_CEILING_HZ, ":", "coherence ceiling", "Color", [0.5 0.5 0.5]);
yline(req.m3CrossoverHz, "--", sprintf("M3 crossover %.2f Hz", req.m3CrossoverHz), ...
    "Color", cReq, "LineWidth", 1.4, "DisplayName", "M3 required crossover");
yline(req.purchaseTargetHz, "-.", sprintf("purchase target %.1f Hz", req.purchaseTargetHz), ...
